"""Ingestion on synthetic clips generated by ffmpeg; no third-party footage is involved."""

from __future__ import annotations

import json
import subprocess
from datetime import UTC, date, datetime
from pathlib import Path

import pytest
from pydantic import ValidationError

from cairoflow_contracts.evidence import ClipLicense, SourceClip, TrimSpec
from cairoflow_perception.ingest import (
    MANIFEST_FILE,
    OUTPUT_FILE,
    IngestError,
    ingest_clip,
    load_source_clip,
    new_run_dir,
    sha256_file,
)

SOURCE_SECONDS = 4
SOURCE_FPS = 30
NOW = datetime(2026, 10, 27, 12, 0, tzinfo=UTC)


def _make_clip(path: Path, size: str) -> Path:
    subprocess.run(
        [
            *("ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error", "-y"),
            *("-f", "lavfi", "-i", f"testsrc2=size={size}:rate={SOURCE_FPS}"),
            *("-t", str(SOURCE_SECONDS), "-c:v", "libx264", "-pix_fmt", "yuv444p", str(path)),
        ],
        check=True,
        capture_output=True,
        stdin=subprocess.DEVNULL,
    )
    return path


@pytest.fixture(scope="module")
def source(tmp_path_factory: pytest.TempPathFactory) -> Path:
    return _make_clip(tmp_path_factory.mktemp("src") / "synthetic.mp4", "320x240")


def _licence(**overrides) -> ClipLicense:
    values = {
        "source_id": "synthetic-testsrc2",
        "source_url": "https://ffmpeg.org/ffmpeg-filters.html#testsrc2",
        "licence_name": "generated in code",
        "attribution": "CairoFlow synthetic test clip (ffmpeg testsrc2)",
        "accessed_on": date(2026, 10, 27),
        "register_ref": "tests/test_ingest.py",
        "permits_commercial_use": True,
        "permits_cloud_processing": True,
        "permits_redistribution": True,
        "share_alike": False,
        "synthetic": True,
    }
    return ClipLicense(**(values | overrides))


def test_ingest_produces_a_10_fps_h264_clip_and_manifest(source: Path, tmp_path: Path) -> None:
    clip = ingest_clip(source, _licence(), tmp_path / "ingest", now=NOW)

    assert clip.source_stream.frame_count == SOURCE_SECONDS * SOURCE_FPS
    assert clip.output_stream.codec == "h264"
    assert clip.output_stream.pixel_format == "yuv420p"
    assert clip.output_stream.fps == pytest.approx(10)
    assert clip.output_stream.frame_count == SOURCE_SECONDS * 10
    assert [f.timestamp_s for f in clip.frames] == pytest.approx([i / 10 for i in range(40)])
    assert clip.source_sha256 == sha256_file(source)
    assert clip.output_sha256 == sha256_file(tmp_path / "ingest" / OUTPUT_FILE)
    assert clip.clip_id == clip.output_sha256[:16]
    assert clip.provenance.kind == "observed"
    assert clip.provenance.input_sha256 == (clip.source_sha256,)
    assert "{source}" in clip.ffmpeg_command and "{output}" in clip.ffmpeg_command
    assert str(tmp_path) not in json.dumps(clip.ffmpeg_command)  # no local paths recorded
    assert load_source_clip(tmp_path / "ingest" / MANIFEST_FILE) == clip


def test_trim_keeps_only_the_requested_window(source: Path, tmp_path: Path) -> None:
    trim = TrimSpec(start_s=1.0, duration_s=2.0)
    clip = ingest_clip(source, _licence(), tmp_path / "ingest", trim=trim, now=NOW)
    assert clip.output_stream.frame_count == 20
    assert clip.frames[0].timestamp_s == 0.0
    assert clip.trim == trim


def test_same_inputs_give_a_byte_identical_clip(source: Path, tmp_path: Path) -> None:
    first = ingest_clip(source, _licence(), tmp_path / "a", now=NOW)
    second = ingest_clip(source, _licence(), tmp_path / "b", now=NOW)
    assert first.output_sha256 == second.output_sha256
    manifest_a = (tmp_path / "a" / MANIFEST_FILE).read_bytes()
    manifest_b = (tmp_path / "b" / MANIFEST_FILE).read_bytes()
    assert manifest_a == manifest_b  # identical when the timestamp is identical


def test_odd_frame_sizes_are_made_even(tmp_path: Path) -> None:
    odd = _make_clip(tmp_path / "odd.mp4", "321x241")
    clip = ingest_clip(odd, _licence(), tmp_path / "ingest", now=NOW)
    assert (clip.output_stream.width_px, clip.output_stream.height_px) == (320, 240)


@pytest.mark.parametrize(
    "overrides", [{"permits_cloud_processing": False}, {"permits_commercial_use": False}]
)
def test_unusable_licence_is_refused_before_anything_is_written(
    source: Path, tmp_path: Path, overrides: dict[str, bool]
) -> None:
    with pytest.raises(IngestError, match="DATA_REGISTER"):
        ingest_clip(source, _licence(**overrides), tmp_path / "ingest")
    assert not (tmp_path / "ingest").exists()


def test_existing_ingest_is_never_overwritten(source: Path, tmp_path: Path) -> None:
    ingest_clip(source, _licence(), tmp_path / "ingest", now=NOW)
    before = (tmp_path / "ingest" / MANIFEST_FILE).read_bytes()
    with pytest.raises(IngestError, match="overwrite"):
        ingest_clip(source, _licence(), tmp_path / "ingest", now=NOW)
    assert (tmp_path / "ingest" / MANIFEST_FILE).read_bytes() == before


@pytest.mark.parametrize("trim", [TrimSpec(start_s=5.0), TrimSpec(start_s=3.0, duration_s=2.0)])
def test_trim_outside_the_source_is_refused(source: Path, tmp_path: Path, trim: TrimSpec) -> None:
    with pytest.raises(IngestError, match="after the end"):
        ingest_clip(source, _licence(), tmp_path / "ingest", trim=trim)


def test_missing_or_non_video_source_is_refused(tmp_path: Path) -> None:
    with pytest.raises(IngestError, match="not found"):
        ingest_clip(tmp_path / "absent.mp4", _licence(), tmp_path / "ingest")
    text = tmp_path / "notes.mp4"
    text.write_text("not a video", encoding="utf-8")
    with pytest.raises(IngestError):
        ingest_clip(text, _licence(), tmp_path / "ingest")
    assert not (tmp_path / "ingest" / OUTPUT_FILE).exists()


def test_tampered_clip_is_detected(source: Path, tmp_path: Path) -> None:
    ingest_clip(source, _licence(), tmp_path / "ingest", now=NOW)
    with (tmp_path / "ingest" / OUTPUT_FILE).open("ab") as handle:
        handle.write(b"\0")
    with pytest.raises(IngestError, match="SHA-256"):
        load_source_clip(tmp_path / "ingest" / MANIFEST_FILE)


def test_manifest_with_inconsistent_frames_is_rejected(source: Path, tmp_path: Path) -> None:
    clip = ingest_clip(source, _licence(), tmp_path / "ingest", now=NOW)
    data = clip.model_dump(mode="json")
    data["frames"] = data["frames"][:-1]
    with pytest.raises(ValidationError, match="every frame"):
        SourceClip.model_validate(data)
    data = clip.model_dump(mode="json")
    data["clip_id"] = "0" * 16
    with pytest.raises(ValidationError, match="clip_id"):
        SourceClip.model_validate(data)


def test_run_dirs_are_new_every_time(tmp_path: Path) -> None:
    first = new_run_dir(tmp_path, now=NOW)
    second = new_run_dir(tmp_path, now=NOW)
    assert first != second and first.name == "ingest" and first.is_dir()
